sp_widget.client_script:
api.controller = function($window) {

    var c = this;


    c.processing = false;
    c.message = '';
    c.actionError = false;


    /* ======================================================
       COMMON ACTION
    ====================================================== */

    c.runAction = function(action) {

        if (c.processing) {
            return;
        }


        c.processing = true;
        c.message = '';
        c.actionError = false;


        c.server.get({

            action: action,

            item_id:
                c.data.item ?
                c.data.item.sys_id :
                '',

            match_id:
                c.data.match ?
                c.data.match.sys_id :
                '',

            claim_id:
                c.data.claim ?
                c.data.claim.sys_id :
                ''

        }).then(

            function(response) {

                c.processing = false;


                if (
                    !response ||
                    !response.data
                ) {

                    c.actionError = true;

                    c.message =
                        'The action could not be completed.';

                    return;
                }


                if (
                    !response.data.success
                ) {

                    c.actionError = true;

                    c.message =
                        response.data.message ||
                        'The action could not be completed.';

                    return;
                }


                c.message =
                    response.data.message ||
                    'Action completed successfully.';


                $window.setTimeout(
                    function() {

                        $window.location.reload();

                    },
                    700
                );

            },

            function() {

                c.processing = false;

                c.actionError = true;

                c.message =
                    'The action could not be completed. Please try again.';

            }

        );

    };


    /* ======================================================
       VERIFY POTENTIAL MATCH
    ====================================================== */

    c.verifyPotentialMatch = function() {

        c.runAction(
            'verifyPotentialMatch'
        );

    };


    /* ======================================================
       SELECT STRONG CANDIDATE
    ====================================================== */

    c.selectCandidate = function() {

        c.runAction(
            'selectCandidate'
        );

    };


    /* ======================================================
       REJECT MATCH
    ====================================================== */

    c.rejectMatch = function() {

        c.runAction(
            'rejectMatch'
        );

    };


    /* ======================================================
       APPROVE CLAIM
    ====================================================== */

    c.approveClaim = function() {

        if (
            !c.data.claim ||
            c.data.claim.actionsLocked ||
            !c.data.claim.canApprove
        ) {

            return;
        }


        c.runAction(
            'approveClaim'
        );

    };


    /* ======================================================
       REJECT CLAIM
    ====================================================== */

    c.rejectClaim = function() {

        if (
            !c.data.claim ||
            c.data.claim.actionsLocked ||
            !c.data.claim.canReject
        ) {

            return;
        }


        c.runAction(
            'rejectClaim'
        );

    };

};

sp_widget.css:
.cm-review-page {
  position: relative;
  display: block;

  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  min-height: 100vh;
  min-height: 100svh;

  padding: 45px 20px 90px;

  background: linear-gradient(180deg,#FBF8EF,#F5F7F0) !important;

  box-shadow:
    0 -60px 0 #FBF8EF,
    0 60px 0 #F5F7F0;

  color: #102E34;
  font-family: "DM Sans","Segoe UI",sans-serif;

  box-sizing: border-box !important;
  overflow-x: hidden;
}

.cm-review-page,
.cm-review-page *,
.cm-review-page *::before,
.cm-review-page *::after {
  box-sizing: border-box;
}

.cm-review-container {
  max-width: 1100px;
  margin: 0 auto;
}

.cm-back {
  display: inline-flex;
  margin-bottom: 26px;
  color: #15564B !important;
  font-size: 12px;
  font-weight: 800;
  text-decoration: none !important;
}

.cm-page-header {
  margin-bottom: 30px;
}

.cm-eyebrow {
  display: inline-flex;
  padding: 7px 14px;
  margin-bottom: 12px;
  border-radius: 999px;
  background: #EDF5E9;
  color: #15564B;
  font-size: 11px;
  font-weight: 800;
}

.cm-page-header h1 {
  margin: 0 0 7px;
  color: #104E45;
  font-family: "Plus Jakarta Sans","Segoe UI",sans-serif;
  font-size: 37px;
}

.cm-page-header p {
  margin: 0;
  color: #687A7E;
  font-size: 13px;
}

/* CARDS */

.cm-main-card,
.cm-item-panel,
.cm-decision-card {
  padding: 25px;
  margin-bottom: 22px;
  border: 1px solid #D2DED8;
  border-radius: 22px;
  background: #FFFFFF;
  box-shadow: 0 5px 18px rgba(16,78,69,.06);
}

.cm-card-heading {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 17px;
}

.cm-card-heading h2 {
  margin: 8px 0 2px;
  color: #104E45;
  font-size: 22px;
}

.cm-number {
  color: #849194;
  font-size: 10px;
}

.cm-status-pill {
  height: fit-content;
  padding: 6px 10px;
  border-radius: 999px;
  background: #FDF3DC;
  color: #856419;
  font-size: 9px;
  font-weight: 800;
}

.cm-type-badge {
  display: inline-flex;
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
}

.cm-type-badge.lost {
  background: #FBEAE7;
  color: #B5502F;
}

.cm-type-badge.found {
  background: #EDF5E9;
  color: #15564B;
}

.cm-description {
  color: #617477;
  font-size: 12px;
  line-height: 1.6;
}

/* DETAIL GRIDS */

.cm-detail-grid,
.cm-mini-details {
  display: grid;
  grid-template-columns: repeat(2,1fr);
  gap: 11px;
}

.cm-detail-grid > div,
.cm-mini-details > div {
  padding: 12px;
  border-radius: 12px;
  background: #F5F8F3;
}

.cm-detail-grid span,
.cm-mini-details span {
  display: block;
  margin-bottom: 4px;
  color: #7B898D;
  font-size: 8px;
}

.cm-detail-grid strong,
.cm-mini-details strong {
  color: #102E34;
  font-size: 10px;
  word-break: break-word;
}

.cm-detail-grid a {
  color: #168C70 !important;
  font-size: 10px;
  font-weight: 800;
  text-decoration: none !important;
}

/* SUBSECTION */

.cm-subsection {
  margin-top: 25px;
}

.cm-subsection h3 {
  color: #104E45;
  font-size: 14px;
}

/* PRIVATE */

.cm-private-box {
  padding: 18px;
  margin-top: 22px;
  border-radius: 17px;
  background: #EDF5E9;
}

.cm-private-heading {
  display: flex;
  gap: 10px;
  margin-bottom: 13px;
}

.cm-private-heading h3 {
  margin: 0;
  color: #104E45;
  font-size: 13px;
}

.cm-private-heading p {
  margin: 2px 0 0;
  color: #718185;
  font-size: 9px;
}

.cm-private-grid {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 9px;
}

.cm-private-grid > div {
  padding: 11px;
  border-radius: 11px;
  background: #FFFFFF;
}

.cm-private-grid span {
  display: block;
  margin-bottom: 4px;
  color: #7B898D;
  font-size: 8px;
}

.cm-private-grid strong {
  color: #102E34;
  font-size: 10px;
}

/* SECTION HEADER */

.cm-section-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 17px;
}

.cm-section-heading h2 {
  margin: 0;
  color: #104E45;
  font-size: 18px;
}

.cm-section-heading > span {
  min-width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #EDF5E9;
  color: #15564B;
  font-size: 9px;
  font-weight: 800;
}

/* RELATED */

.cm-related-list {
  display: grid;
  gap: 9px;
}

.cm-related-match {
  padding: 12px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-radius: 12px;
  background: #F5F8F3;
  text-decoration: none !important;
}

.cm-related-match strong {
  display: block;
  color: #104E45;
  font-size: 11px;
}

.cm-related-match span {
  color: #7A898D;
  font-size: 8px;
}

.cm-related-match b {
  color: #168C70;
  font-size: 15px;
}

/* SCORE SUMMARY */

.cm-score-summary,
.cm-claim-summary {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: 12px;
  margin-bottom: 22px;
}

.cm-score-summary > div,
.cm-claim-summary > div {
  padding: 16px;
  border: 1px solid #D2DED8;
  border-radius: 15px;
  background: #FFFFFF;
}

.cm-score-summary span,
.cm-claim-summary span {
  display: block;
  margin-bottom: 5px;
  color: #7A898D;
  font-size: 8px;
}

.cm-score-summary strong,
.cm-claim-summary strong {
  color: #104E45;
  font-size: 18px;
}

/* MATCH COMPARISON */

.cm-comparison {
  display: grid;
  grid-template-columns: 1fr 55px 1fr;
  align-items: center;
  gap: 13px;
  margin-bottom: 22px;
}

.cm-item-panel h2 {
  margin: 10px 0 7px;
  color: #104E45;
  font-size: 18px;
}

.cm-item-panel > p {
  color: #687A7E;
  font-size: 10px;
  line-height: 1.5;
}

.cm-versus {
  width: 44px;
  height: 44px;
  margin: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #EDF5E9;
  color: #249D78;
  font-size: 18px;
}

/* FACTORS */

.cm-factor-grid {
  display: grid;
  grid-template-columns: repeat(2,1fr);
  gap: 20px 28px;
}

.cm-factor {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 7px;
}

.cm-factor strong {
  display: block;
  color: #102E34;
  font-size: 10px;
}

.cm-factor span {
  color: #879397;
  font-size: 8px;
}

.cm-factor b {
  color: #15564B;
  font-size: 11px;
}

.cm-track {
  grid-column: 1 / -1;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: #EDF2EE;
}

.cm-fill {
  height: 100%;
  border-radius: inherit;
  background: #249D78;
}

/* ANSWERS */

.cm-answer-table {
  display: grid;
  gap: 12px;
}

.cm-answer-block {
  display: grid;
  grid-template-columns: 34px 1fr 1fr;
  gap: 12px;
  align-items: stretch;
}

.cm-answer-number {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: #EDF5E9;
  color: #15564B;
  font-size: 10px;
  font-weight: 800;
}

.cm-answer-block > div {
  padding: 12px;
  border-radius: 12px;
  background: #F5F8F3;
}

.cm-answer-label {
  display: block;
  margin-bottom: 4px;
  color: #7A898D;
  font-size: 8px;
}

.cm-answer-block strong {
  color: #102E34;
  font-size: 10px;
  line-height: 1.5;
}

/* DECISION */

.cm-decision-card {
  background: linear-gradient(135deg,#104E45,#156B5B);
  color: #FFFFFF;
  text-align: center;
}

.cm-decision-label {
  color: #BDE8D8;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.cm-decision-card h2 {
  margin: 7px 0;
  color: #FFFFFF;
  font-size: 20px;
}

.cm-decision-card p {
  max-width: 650px;
  margin: 0 auto 20px;
  color: rgba(255,255,255,.72);
  font-size: 10px;
  line-height: 1.6;
}

.cm-decision-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
}

.cm-decision-actions button {
  min-width: 170px;
  padding: 12px 17px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

.cm-approve {
  border: 0;
  background: #FFFFFF;
  color: #104E45;
}

.cm-reject {
  border: 1px solid rgba(255,255,255,.55);
  background: transparent;
  color: #FFFFFF;
}

/* MESSAGE */

.cm-action-message {
  padding: 12px 15px;
  margin-bottom: 19px;
  border-radius: 13px;
  background: #E4F4EA;
  color: #14765C;
  font-size: 11px;
  font-weight: 700;
}

.cm-action-message.error {
  background: #FBEAE7;
  color: #A44832;
}

/* STATES */

.cm-state-card {
  max-width: 480px;
  margin: 50px auto;
  padding: 50px 28px;
  border: 1px solid #D2DED8;
  border-radius: 22px;
  background: #FFFFFF;
  text-align: center;
}

.cm-state-icon {
  width: 60px;
  height: 60px;
  margin: 0 auto 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #FBEAE7;
  color: #B5502F;
  font-size: 22px;
  font-weight: 800;
}

.cm-state-card h2 {
  color: #104E45;
}

.cm-state-card p,
.cm-empty {
  color: #718185;
  font-size: 11px;
}

/* MOBILE */

@media (max-width: 760px) {

  .cm-comparison {
    grid-template-columns: 1fr;
  }

  .cm-score-summary,
  .cm-claim-summary {
    grid-template-columns: repeat(2,1fr);
  }

  .cm-versus {
    transform: rotate(90deg);
  }

  .cm-private-grid,
  .cm-factor-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {

  .cm-review-page {
    min-height: 100svh;

    padding: 30px 14px 65px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F5F7F0;
  }

  .cm-page-header h1 {
    font-size: 29px;
  }

  .cm-detail-grid,
  .cm-mini-details {
    grid-template-columns: 1fr;
  }

  .cm-answer-block {
    grid-template-columns: 32px 1fr;
  }

  .cm-answer-block > div {
    grid-column: 2;
  }

  .cm-decision-actions {
    flex-direction: column;
  }

  .cm-decision-actions button {
    width: 100%;
  }
}

/* ==========================================================
   CLOSED / WITHDRAWN STATE
========================================================== */

.cm-locked-card {
  margin-bottom: 22px;
  padding: 20px 22px;

  display: flex;
  align-items: flex-start;

  gap: 14px;

  border: 1px solid #D2DED8;
  border-radius: 18px;

  background: #F5F8F3;
}

.cm-locked-icon {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  background: #EDF5E9;

  color: #168C70;

  font-size: 15px;
  font-weight: 900;
}

.cm-locked-card h3 {
  margin: 1px 0 5px;

  color: #104E45;

  font-size: 14px;
  font-weight: 800;
}

.cm-locked-card p {
  margin: 0;

  color: #617477;

  font-size: 10px;
  line-height: 1.6;
}

/* ==========================================================
   STAFF REVIEW - ITEM IMAGES
========================================================== */


/* ----------------------------------------------------------
   SINGLE ITEM REVIEW IMAGE SECTION
---------------------------------------------------------- */

.cm-review-image-section {
  width: 100%;

  margin: 22px 0 24px;
  padding: 18px;

  border: 1px solid #D2DED8;
  border-radius: 17px;

  background: #F8FAF7;

  box-sizing: border-box;
}

.cm-review-image-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 16px;

  margin-bottom: 14px;
}

.cm-review-image-heading h3 {
  margin: 0 0 4px;

  color: #104E45;

  font-size: 14px;
  font-weight: 800;
}

.cm-review-image-heading p {
  margin: 0;

  color: #718185;

  font-size: 10px;
  line-height: 1.5;
}

.cm-image-private-badge {
  flex-shrink: 0;

  padding: 6px 10px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 9px;
  font-weight: 800;
}

/* ----------------------------------------------------------
   IMAGE FRAME
---------------------------------------------------------- */

.cm-review-image-frame {
  width: 100%;

  height: 320px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;

  border: 1px solid #DCE6E1;
  border-radius: 15px;

  background: #EEF3EF;
}

.cm-review-image-frame img {
  display: block;

  width: 100%;
  height: 100%;

  object-fit: contain;

  background: #EEF3EF;
}

/* ----------------------------------------------------------
   EMPTY STATE
---------------------------------------------------------- */

.cm-review-image-empty {
  width: 100%;
  min-height: 170px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 5px;

  border: 1px dashed #C8D7D0;
  border-radius: 15px;

  background: #F4F8F3;

  color: #718185;
}

.cm-review-image-empty-icon {
  margin-bottom: 3px;

  color: #9AABA5;

  font-size: 30px;
}

.cm-review-image-empty strong {
  color: #506267;

  font-size: 11px;
}

.cm-review-image-empty span {
  font-size: 9px;
}

/* ==========================================================
   MATCH REVIEW - LOST / FOUND IMAGES
========================================================== */

.cm-match-review-image {
  width: 100%;
  height: 220px;

  margin: 17px 0;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;

  border: 1px solid #DCE6E1;
  border-radius: 14px;

  background: #F2F6F2;
}

.cm-match-review-image img {
  display: block;

  width: 100%;
  height: 100%;

  object-fit: contain;

  background: #F2F6F2;
}

.cm-match-image-empty {
  width: 100%;
  height: 100%;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 7px;

  color: #81908C;

  text-align: center;
}

.cm-match-image-empty > span {
  font-size: 27px;
}

.cm-match-image-empty strong {
  color: #687A7E;

  font-size: 10px;
}

/* ==========================================================
   TABLET
========================================================== */

@media (max-width: 850px) {

  .cm-review-image-frame {
    height: 280px;
  }

  .cm-match-review-image {
    height: 190px;
  }

}

/* ==========================================================
   MOBILE / NOW MOBILE WEBVIEW
========================================================== */

@media (max-width: 600px) {

  .cm-review-image-section {
    margin:
      18px
      0
      20px;

    padding: 13px;
  }

  .cm-review-image-heading {
    flex-direction: column;

    gap: 9px;
  }

  .cm-review-image-frame {
    height: 230px;
  }

  .cm-match-review-image {
    height: 210px;

    margin:
      14px
      0;
  }

}

/* ==========================================================
   WITHDRAWN MATCH NOTICE - NEUTRAL SLATE BLUE
========================================================== */

.cm-withdrawn-banner {
  width: 100%;

  margin: 0 0 20px;
  padding: 15px 17px;

  display: flex;
  align-items: flex-start;
  gap: 12px;

  border: 1px solid #E7CFCB;
  border-left: 4px solid #B86F67;
  border-radius: 14px;

  background: #FBF1EF;

  box-shadow:
    0 4px 14px rgba(125, 79, 73, 0.06);

  box-sizing: border-box;
}

.cm-withdrawn-banner .cm-info-banner-icon {
  width: 30px;
  height: 30px;
  min-width: 30px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #F2DDD9;
  color: #8F514A;

  font-size: 14px;
  font-weight: 900;
}

.cm-withdrawn-banner .cm-info-banner-content {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;

  padding-top: 1px;
}

.cm-withdrawn-banner .cm-info-banner-content strong {
  display: block;

  color: #6F3F3A;

  font-size: 12px;
  font-weight: 800;

  line-height: 1.4;
}

.cm-withdrawn-banner .cm-info-banner-content span {
  display: block;

  color: #84615D;

  font-size: 10px;
  font-weight: 500;

  line-height: 1.6;
}

/* MOBILE */

@media (max-width: 560px) {

  .cm-withdrawn-banner {
    padding: 13px 14px;
    gap: 10px;
  }

  .cm-info-banner-icon {
    width: 28px;
    height: 28px;

    min-width: 28px;

    font-size: 13px;
  }

}

sp_widget.script:
(function() {

    /* ======================================================
       TABLES
    ====================================================== */

    var ITEM_TABLE =
        'x_snc_campusmatch_campusmatch_item';

    var MATCH_TABLE =
        'x_snc_campusmatch_campusmatch_match';

    var CLAIM_TABLE =
        'x_snc_campusmatch_campusmatch_claim';


    /* ======================================================
       ITEM FIELDS
    ====================================================== */

    var I_NUMBER = 'number';
    var I_TYPE = 'report_type';
    var I_TITLE = 'title';
    var I_PUBLIC_TITLE = 'public_title';
    var I_DESCRIPTION = 'description';
    var I_CATEGORY = 'category';
    var I_BRAND = 'brand';
    var I_COLOR = 'color';
    var I_UNIQUE = 'unique_features';
    var I_LOCATION = 'location_zone';
    var I_X = 'location_x';
    var I_Y = 'location_y';
    var I_REPORTED = 'reported_date_time';
    var I_REPORTER = 'reporter';
    var I_STATUS = 'status';
    var I_AI_TEXT = 'ai_attribute_text';

    /*
     * STAFF-ONLY ITEM IMAGE
     */
    var I_IMAGE = 'image';


    /* ======================================================
       MATCH FIELDS
    ====================================================== */

    var M_LOST = 'lost_item';
    var M_FOUND = 'found_item';
    var M_IMAGE = 'image_similarity';
    var M_DESCRIPTION = 'description_similarity';
    var M_LOCATION = 'location_score';
    var M_TIME = 'time_score';
    var M_CATEGORY = 'category_score';
    var M_UNIQUE = 'unique_attribute_score';
    var M_OVERALL = 'overall_score';
    var M_LEVEL = 'match_level';
    var M_STATUS = 'status';
    var M_EXPLANATION = 'explanation';

    var M_DECISION_REASON =
        'decision_reason';


    /* ======================================================
       CLAIM FIELDS
    ====================================================== */

    var C_NUMBER = 'number';
    var C_MATCH = 'match';
    var C_ITEM = 'item';
    var C_CLAIMANT = 'claimant';
    var C_STATUS = 'claim_status';
    var C_DATE = 'claim_date';

    var C_A1 =
        'u_claimant_answer_1';

    var C_A2 =
        'u_claimant_answer_2';

    var C_A3 =
        'u_claimant_answer_3';

    var C_SCORE =
        'u_verification_score';

    var C_RESULT =
        'u_verification_result';

    var C_VERIFIED_BY =
        'verified_by';

    var C_VERIFIED_ON =
        'verified_on';


    /* ======================================================
       MATCH CHOICE VALUES
    ====================================================== */

    var MATCH_ACTIVE =
        'active';

    var MATCH_CONFIRMED =
        'confirmed';

    var MATCH_REJECTED =
        'no_match';

    var MATCH_WITHDRAWN =
        'withdrawn';


    /* ======================================================
       DECISION REASONS
    ====================================================== */

    var DECISION_SELECTED =
        'selected_candidate';

    var DECISION_COMPETING =
        'competing_candidate';

    var DECISION_STAFF_REJECTED =
        'staff_rejected';

    var DECISION_CLAIM_WITHDRAWN =
        'claim_withdrawn';


    /* ======================================================
       CLAIM CHOICE VALUES
    ====================================================== */

    /*
     * Internal choice values are handled through helper
     * functions below so the script works whether the
     * instance stores them as lowercase values or labels.
     */

    var CLAIM_APPROVED =
        'approved';

    var CLAIM_REJECTED =
        'rejected';

    var CLAIM_WITHDRAWN =
        'withdrawn';


    /* ======================================================
       DEFAULT DATA
    ====================================================== */

    data.error = '';
    data.success = false;
    data.message = '';

    data.item = null;
    data.match = null;
    data.claim = null;

    data.relatedMatches = [];


    /* ======================================================
       STAFF SECURITY
    ====================================================== */

    var access =
        new CampusMatchAccess();

    data.isStaff =
        access.isStaff();

    data.isAdmin =
        data.isStaff;

    data.allowed =
        data.isStaff;


    if (!data.allowed) {

        data.error =
            'Staff access required.';

        return;
    }


    /* ======================================================
       HELPERS
    ====================================================== */

    function normalize(v) {

        return (
            v || ''
        )
        .toString()
        .toLowerCase()
        .trim();
    }


    function firstValidItemField(
        candidates
    ) {

        var test =
            new GlideRecord(
                ITEM_TABLE
            );

        for (
            var i = 0;
            i < candidates.length;
            i++
        ) {

            if (
                test.isValidField(
                    candidates[i]
                )
            ) {

                return candidates[i];
            }
        }

        return '';
    }


    var I_PRIVATE_1 =
        firstValidItemField([
            'private_detail_1',
            'u_private_detail_1',
            'private_ownership_detail_1',
            'u_private_ownership_detail_1',
            'ownership_detail_1',
            'u_ownership_detail_1'
        ]);


    var I_PRIVATE_2 =
        firstValidItemField([
            'private_detail_2',
            'u_private_detail_2',
            'private_ownership_detail_2',
            'u_private_ownership_detail_2',
            'ownership_detail_2',
            'u_ownership_detail_2'
        ]);


    var I_PRIVATE_3 =
        firstValidItemField([
            'private_detail_3',
            'u_private_detail_3',
            'private_ownership_detail_3',
            'u_private_ownership_detail_3',
            'ownership_detail_3',
            'u_ownership_detail_3'
        ]);


    function display(
        gr,
        field,
        fallback
    ) {

        if (
            !gr ||
            !field ||
            !gr.isValidField(field)
        ) {

            return fallback || '—';
        }

        return (
            gr.getDisplayValue(
                field
            ) ||
            fallback ||
            '—'
        );
    }


    function value(
        gr,
        field
    ) {

        if (
            !gr ||
            !field ||
            !gr.isValidField(field)
        ) {

            return '';
        }

        return (
            gr.getValue(
                field
            ) || ''
        );
    }


    /* ======================================================
       STAFF-ONLY IMAGE URL
    ====================================================== */

    function getItemImageUrl(gr) {

        if (
            !data.isStaff ||
            !gr
        ) {

            return '';
        }

        var itemSysId =
            gr.getUniqueValue();

        if (!itemSysId) {
            return '';
        }


        /* ==================================================
           CURRENT CAMPUSMATCH IMAGE ATTACHMENT
        ================================================== */

        var imageAttachment =
            new GlideRecord(
                'sys_attachment'
            );

        imageAttachment.addQuery(
            'table_sys_id',
            itemSysId
        );

        imageAttachment.addQuery(
            'table_name',
            'ZZ_YY' + ITEM_TABLE
        );

        imageAttachment.addQuery(
            'file_name',
            'image'
        );

        imageAttachment.orderByDesc(
            'sys_created_on'
        );

        imageAttachment.setLimit(
            1
        );

        imageAttachment.query();


        if (
            imageAttachment.next()
        ) {

            return '/' +
                imageAttachment.getUniqueValue() +
                '.iix';
        }


        /* ==================================================
           FALLBACK FOR OLDER IMAGE ATTACHMENTS
        ================================================== */

        var oldImage =
            new GlideRecord(
                'sys_attachment'
            );

        oldImage.addQuery(
            'table_sys_id',
            itemSysId
        );

        oldImage.addQuery(
            'table_name',
            ITEM_TABLE
        );

        oldImage.addQuery(
            'content_type',
            'STARTSWITH',
            'image/'
        );

        oldImage.orderByDesc(
            'sys_created_on'
        );

        oldImage.setLimit(
            1
        );

        oldImage.query();


        if (
            oldImage.next()
        ) {

            return '/' +
                oldImage.getUniqueValue() +
                '.iix';
        }


        return '';
    }


    function numberValue(
        gr,
        field
    ) {

        var n =
            parseFloat(
                value(
                    gr,
                    field
                )
            );

        if (
            isNaN(n)
        ) {

            return 0;
        }

        return Math.round(
            n * 100
        ) / 100;
    }


    function loadItem(
        sysId
    ) {

        if (!sysId) {
            return null;
        }

        var gr =
            new GlideRecord(
                ITEM_TABLE
            );

        if (
            gr.get(
                sysId
            )
        ) {

            return gr;
        }

        return null;
    }


    function itemObject(
        gr
    ) {

        if (!gr) {
            return null;
        }

        var type =
            normalize(
                value(
                    gr,
                    I_TYPE
                )
            );

        return {

            sys_id:
                gr.getUniqueValue(),

            number:
                display(
                    gr,
                    I_NUMBER,
                    ''
                ),

            reportType:
                type,

            reportTypeLabel:
                type === 'found'
                    ?
                    'Found'
                    :
                    'Lost',

            title:
                value(
                    gr,
                    I_TITLE
                ) ||
                display(
                    gr,
                    I_PUBLIC_TITLE,
                    'CampusMatch Item'
                ),

            publicTitle:
                display(
                    gr,
                    I_PUBLIC_TITLE,
                    '—'
                ),

            description:
                display(
                    gr,
                    I_DESCRIPTION,
                    '—'
                ),

            category:
                display(
                    gr,
                    I_CATEGORY,
                    '—'
                ),

            brand:
                display(
                    gr,
                    I_BRAND,
                    '—'
                ),

            color:
                display(
                    gr,
                    I_COLOR,
                    '—'
                ),

            uniqueFeatures:
                display(
                    gr,
                    I_UNIQUE,
                    '—'
                ),

            aiAttributeText:
                display(
                    gr,
                    I_AI_TEXT,
                    '—'
                ),

            location:
                display(
                    gr,
                    I_LOCATION,
                    '—'
                ),

            locationX:
                display(
                    gr,
                    I_X,
                    '—'
                ),

            locationY:
                display(
                    gr,
                    I_Y,
                    '—'
                ),

            reported:
                display(
                    gr,
                    I_REPORTED,
                    '—'
                ),

            reporter:
                display(
                    gr,
                    I_REPORTER,
                    '—'
                ),

            status:
                display(
                    gr,
                    I_STATUS,
                    '—'
                ),

            private1:
                display(
                    gr,
                    I_PRIVATE_1,
                    '—'
                ),

            private2:
                display(
                    gr,
                    I_PRIVATE_2,
                    '—'
                ),

            private3:
                display(
                    gr,
                    I_PRIVATE_3,
                    '—'
                ),

            imageUrl:
                getItemImageUrl(
                    gr
                )
        };
    }


    /* ======================================================
       MATCH LEVEL
    ====================================================== */

    function getMatchLevel(
        match
    ) {

        var level =
            normalize(
                match.getValue(
                    M_LEVEL
                )
            );


        /*
         * Normalize common stored values.
         */

        if (
            level ===
                'potential_match'
        ) {

            level =
                'potential';
        }


        if (
            level ===
                'strong_match'
        ) {

            level =
                'strong';
        }


        if (
            level ===
                'no_match'
        ) {

            return 'low';
        }


        if (level) {

            return level;
        }


        /*
         * Score fallback.
         */

        var overall =
            numberValue(
                match,
                M_OVERALL
            );


        if (
            overall >= 80
        ) {

            return 'strong';
        }


        if (
            overall >= 65
        ) {

            return 'potential';
        }


        return 'low';
    }


    /* ======================================================
       POTENTIAL STAFF VERIFICATION
    ====================================================== */

    function isPotentialStaffVerified(
        match
    ) {

        var status =
            normalize(
                match.getValue(
                    M_STATUS
                )
            );


        /*
         * Confirmed also means review is complete.
         */

        if (
            status ===
                MATCH_CONFIRMED
        ) {

            return true;
        }


        if (
            status !==
                MATCH_ACTIVE
        ) {

            return false;
        }


        var reviewed =
            false;


        if (
            match.isValidField(
                'reviewed_by'
            ) &&
            match.getValue(
                'reviewed_by'
            )
        ) {

            reviewed =
                true;
        }


        if (
            match.isValidField(
                'reviewed_on'
            ) &&
            match.getValue(
                'reviewed_on'
            )
        ) {

            reviewed =
                true;
        }


        return reviewed;
    }


    /* ======================================================
       FACTORS
    ====================================================== */

    function factorArray(
        match
    ) {

        return [

            {
                label:
                    'Image Attributes',

                score:
                    numberValue(
                        match,
                        M_IMAGE
                    ),

                weight:
                    35
            },

            {
                label:
                    'Description',

                score:
                    numberValue(
                        match,
                        M_DESCRIPTION
                    ),

                weight:
                    20
            },

            {
                label:
                    'Location',

                score:
                    numberValue(
                        match,
                        M_LOCATION
                    ),

                weight:
                    15
            },

            {
                label:
                    'Time',

                score:
                    numberValue(
                        match,
                        M_TIME
                    ),

                weight:
                    10
            },

            {
                label:
                    'Category',

                score:
                    numberValue(
                        match,
                        M_CATEGORY
                    ),

                weight:
                    10
            },

            {
                label:
                    'Unique Attributes',

                score:
                    numberValue(
                        match,
                        M_UNIQUE
                    ),

                weight:
                    10
            }

        ];
    }


    /* ======================================================
       CLAIM STATUS HELPER
    ====================================================== */

    function setClaimStatus(
        gr,
        desiredValue
    ) {

        if (
            !gr ||
            !gr.isValidField(
                C_STATUS
            )
        ) {

            return false;
        }


        var element =
            gr.getElement(
                C_STATUS
            );


        if (!element) {
            return false;
        }


        /*
         * Try internal value first.
         */

        try {

            element.setValue(
                desiredValue
            );

            return true;

        }
        catch (e) {
            /*
             * Continue to fallback.
             */
        }


        return false;
    }


    /* ======================================================
       INPUT PARAMETERS
    ====================================================== */

    var itemId =
        input &&
        input.item_id
            ?
            input.item_id
            :
            $sp.getParameter(
                'item_id'
            );


    var matchId =
        input &&
        input.match_id
            ?
            input.match_id
            :
            $sp.getParameter(
                'match_id'
            );


    var claimId =
        input &&
        input.claim_id
            ?
            input.claim_id
            :
            $sp.getParameter(
                'claim_id'
            );


    /* ======================================================
       ACTIONS
    ====================================================== */

    if (
        input &&
        input.action
    ) {


        /* ==================================================
           VERIFY POTENTIAL MATCH
        ================================================== */

        if (
            input.action ===
                'verifyPotentialMatch'
        ) {

            var verifyId =
                (
                    input.match_id ||
                    matchId ||
                    ''
                )
                .toString()
                .trim();


            var verifyMatch =
                new GlideRecord(
                    MATCH_TABLE
                );


            if (
                !verifyId ||
                !verifyMatch.get(
                    verifyId
                )
            ) {

                data.success =
                    false;

                data.message =
                    'Match could not be found.';

                return;
            }


            var currentStatus =
                normalize(
                    verifyMatch.getValue(
                        M_STATUS
                    )
                );


            if (
                currentStatus ===
                    MATCH_REJECTED ||
                currentStatus ===
                    'rejected'
            ) {

                data.success =
                    false;

                data.message =
                    'This Match has already been rejected.';

                return;
            }


            if (
                currentStatus ===
                    MATCH_WITHDRAWN
            ) {

                data.success =
                    false;

                data.message =
                    'This Match was withdrawn and cannot be reviewed again.';

                return;
            }


            if (
                currentStatus ===
                    MATCH_CONFIRMED ||
                currentStatus ===
                    'resolved'
            ) {

                data.success =
                    false;

                data.message =
                    'This Match is already closed and cannot be reviewed again.';

                return;
            }


            var verifyLevel =
                getMatchLevel(
                    verifyMatch
                );


            if (
                verifyLevel !==
                    'potential'
            ) {

                data.success =
                    false;

                data.message =
                    'Only Potential Matches require this review.';

                return;
            }


            /*
             * Staff accepted the Potential Match.
             *
             * Keep Confirmed reserved for successful
             * ownership verification.
             */

            verifyMatch.setValue(
                M_STATUS,
                MATCH_ACTIVE
            );


            if (
                verifyMatch.isValidField(
                    M_DECISION_REASON
                )
            ) {

                verifyMatch.setValue(
                    M_DECISION_REASON,
                    ''
                );
            }


            if (
                verifyMatch.isValidField(
                    'reviewed_by'
                )
            ) {

                verifyMatch.setValue(
                    'reviewed_by',
                    gs.getUserID()
                );
            }


            if (
                verifyMatch.isValidField(
                    'reviewed_on'
                )
            ) {

                verifyMatch.setValue(
                    'reviewed_on',
                    new GlideDateTime()
                );
            }


            verifyMatch.update();


            data.success =
                true;

            data.message =
                'Potential Match verified. The Lost reporter can now begin ownership verification.';

            return;
        }


        /* ==================================================
           REJECT MATCH
        ================================================== */

        if (
            input.action ===
                'rejectMatch'
        ) {

            var rejectId =
                (
                    input.match_id ||
                    matchId ||
                    ''
                )
                .toString()
                .trim();


            var rejectedMatch =
                new GlideRecord(
                    MATCH_TABLE
                );


            if (
                !rejectId ||
                !rejectedMatch.get(
                    rejectId
                )
            ) {

                data.success =
                    false;

                data.message =
                    'Match could not be found.';

                return;
            }


            var rejectStatus =
                normalize(
                    rejectedMatch.getValue(
                        M_STATUS
                    )
                );


            if (
                rejectStatus ===
                    MATCH_CONFIRMED
            ) {

                data.success =
                    false;

                data.message =
                    'A confirmed Match cannot be rejected here.';

                return;
            }


            if (
                rejectStatus ===
                    MATCH_WITHDRAWN
            ) {

                data.success =
                    false;

                data.message =
                    'A withdrawn Match cannot be rejected or reviewed again.';

                return;
            }


            if (
                rejectStatus ===
                    'resolved'
            ) {

                data.success =
                    false;

                data.message =
                    'A resolved Match cannot be rejected here.';

                return;
            }


            rejectedMatch.setValue(
                M_STATUS,
                MATCH_REJECTED
            );


            if (
                rejectedMatch.isValidField(
                    M_DECISION_REASON
                )
            ) {

                rejectedMatch.setValue(
                    M_DECISION_REASON,
                    DECISION_STAFF_REJECTED
                );
            }


            if (
                rejectedMatch.isValidField(
                    'reviewed_by'
                )
            ) {

                rejectedMatch.setValue(
                    'reviewed_by',
                    gs.getUserID()
                );
            }


            if (
                rejectedMatch.isValidField(
                    'reviewed_on'
                )
            ) {

                rejectedMatch.setValue(
                    'reviewed_on',
                    new GlideDateTime()
                );
            }


            rejectedMatch.update();


            data.success =
                true;

            data.message =
                'Match rejected. It can no longer proceed to ownership verification.';

            return;
        }


        /* ==================================================
           MULTIPLE STRONG MATCHES
           SELECT ONE CANDIDATE

           IMPORTANT:
           Candidates are grouped by LOST ITEM.

           Example:

           Lost A
             ├── Found 1 → Strong
             └── Found 2 → Strong

           Selecting one closes the other Found
           candidate for the SAME Lost item.
        ================================================== */

        if (
            input.action ===
                'selectCandidate'
        ) {

            var selectedMatchId =
                (
                    input.match_id ||
                    matchId ||
                    ''
                )
                .toString()
                .trim();


            var selectedMatch =
                new GlideRecord(
                    MATCH_TABLE
                );


            if (
                !selectedMatchId ||
                !selectedMatch.get(
                    selectedMatchId
                )
            ) {

                data.success =
                    false;

                data.message =
                    'Selected Match could not be found.';

                return;
            }


            var selectedStatus =
                normalize(
                    selectedMatch.getValue(
                        M_STATUS
                    )
                );


            if (
                selectedStatus ===
                    MATCH_WITHDRAWN
            ) {

                data.success =
                    false;

                data.message =
                    'A withdrawn Match cannot be selected again.';

                return;
            }


            if (
                selectedStatus ===
                    MATCH_REJECTED ||
                selectedStatus ===
                    'rejected' ||
                selectedStatus ===
                    MATCH_CONFIRMED ||
                selectedStatus ===
                    'resolved'
            ) {

                data.success =
                    false;

                data.message =
                    'This Match is already closed and cannot be selected.';

                return;
            }


            var selectedLostId =
                selectedMatch.getValue(
                    M_LOST
                );


            if (!selectedLostId) {

                data.success =
                    false;

                data.message =
                    'The selected Match does not contain a Lost Item.';

                return;
            }


            var selectedFoundId =
                selectedMatch.getValue(
                    M_FOUND
                );


            if (!selectedFoundId) {

                data.success =
                    false;

                data.message =
                    'The selected Match does not contain a Found Item.';

                return;
            }


            /* ==================================================
               CLOSE COMPETING FOUND CANDIDATES FOR SAME LOST ITEM
            ================================================== */

            var otherMatches =
                new GlideRecord(
                    MATCH_TABLE
                );


            /*
             * IMPORTANT FIX:
             *
             * Group by LOST item, not FOUND item.
             *
             * This matches CampusMatch's Multiple Strong
             * Match scenario.
             */

            otherMatches.addQuery(
                M_LOST,
                selectedLostId
            );


            otherMatches.addQuery(
                'sys_id',
                '!=',
                selectedMatchId
            );


            /*
             * Only Potential / Strong candidates can compete.
             */

            otherMatches.addQuery(
                M_OVERALL,
                '>=',
                65
            );


            otherMatches.query();


            while (
                otherMatches.next()
            ) {

                var otherStatus =
                    normalize(
                        otherMatches.getValue(
                            M_STATUS
                        )
                    );


                if (
                    otherStatus ===
                        'resolved' ||
                    otherStatus ===
                        MATCH_CONFIRMED ||
                    otherStatus ===
                        MATCH_WITHDRAWN ||
                    otherStatus ===
                        MATCH_REJECTED ||
                    otherStatus ===
                        'rejected'
                ) {

                    continue;
                }


                otherMatches.setValue(
                    M_STATUS,
                    MATCH_REJECTED
                );


                /*
                 * These were not manually rejected.
                 * They were closed because another
                 * candidate was selected.
                 */

                if (
                    otherMatches.isValidField(
                        M_DECISION_REASON
                    )
                ) {

                    otherMatches.setValue(
                        M_DECISION_REASON,
                        DECISION_COMPETING
                    );
                }


                if (
                    otherMatches.isValidField(
                        'reviewed_by'
                    )
                ) {

                    otherMatches.setValue(
                        'reviewed_by',
                        gs.getUserID()
                    );
                }


                if (
                    otherMatches.isValidField(
                        'reviewed_on'
                    )
                ) {

                    otherMatches.setValue(
                        'reviewed_on',
                        new GlideDateTime()
                    );
                }


                otherMatches.update();
            }


            /*
             * Selected candidate stays Active.
             *
             * Ownership verification still has to happen.
             */

            selectedMatch.setValue(
                M_STATUS,
                MATCH_ACTIVE
            );


            if (
                selectedMatch.isValidField(
                    M_DECISION_REASON
                )
            ) {

                selectedMatch.setValue(
                    M_DECISION_REASON,
                    DECISION_SELECTED
                );
            }


            if (
                selectedMatch.isValidField(
                    'reviewed_by'
                )
            ) {

                selectedMatch.setValue(
                    'reviewed_by',
                    gs.getUserID()
                );
            }


            if (
                selectedMatch.isValidField(
                    'reviewed_on'
                )
            ) {

                selectedMatch.setValue(
                    'reviewed_on',
                    new GlideDateTime()
                );
            }


            selectedMatch.update();


            data.success =
                true;

            data.message =
                'Candidate selected. Other eligible matches for this Lost Item were closed as competing candidates.';

            return;
        }


        /* ==================================================
           APPROVE OWNERSHIP CLAIM
        ================================================== */

        if (
            input.action ===
                'approveClaim'
        ) {

            var approvalClaim =
                new GlideRecord(
                    CLAIM_TABLE
                );


            if (
                !claimId ||
                !approvalClaim.get(
                    claimId
                )
            ) {

                data.success =
                    false;

                data.message =
                    'Claim could not be found.';

                return;
            }


            var approvalClaimStatus =
                normalize(
                    approvalClaim.getValue(
                        C_STATUS
                    )
                );


            if (
                approvalClaimStatus ===
                    CLAIM_WITHDRAWN
            ) {

                data.success =
                    false;

                data.message =
                    'This Claim was withdrawn by the claimant and cannot be approved.';

                return;
            }


            if (
                approvalClaimStatus ===
                    'rejected' ||
                approvalClaimStatus ===
                    'cancelled' ||
                approvalClaimStatus ===
                    'canceled'
            ) {

                data.success =
                    false;

                data.message =
                    'This Claim is already closed and cannot be approved.';

                return;
            }


            if (
                approvalClaimStatus ===
                    'approved'
            ) {

                data.success =
                    false;

                data.message =
                    'This Claim has already been approved.';

                return;
            }


            /* ==================================================
               LOAD MATCH
            ================================================== */

            var approvalMatchId =
                approvalClaim.getValue(
                    C_MATCH
                );


            var approvalMatch =
                new GlideRecord(
                    MATCH_TABLE
                );


            if (
                !approvalMatchId ||
                !approvalMatch.get(
                    approvalMatchId
                )
            ) {

                data.success =
                    false;

                data.message =
                    'The Match linked to this Claim could not be found.';

                return;
            }


            /* ==================================================
               MATCH MUST STILL BE VALID
            ================================================== */

            var approvalMatchStatus =
                normalize(
                    approvalMatch.getValue(
                        M_STATUS
                    )
                );


            if (
                approvalMatchStatus ===
                    MATCH_WITHDRAWN
            ) {

                data.success =
                    false;

                data.message =
                    'The Match linked to this Claim was withdrawn and cannot be approved.';

                return;
            }


            if (
                approvalMatchStatus ===
                    MATCH_REJECTED ||
                approvalMatchStatus ===
                    'rejected' ||
                approvalMatchStatus ===
                    'resolved'
            ) {

                data.success =
                    false;

                data.message =
                    'The Match linked to this Claim is already closed.';

                return;
            }


            /* ==================================================
               LOAD FOUND ITEM
            ================================================== */

            var approvalFoundId =
                approvalMatch.getValue(
                    M_FOUND
                );


            var approvalFound =
                new GlideRecord(
                    ITEM_TABLE
                );


            if (
                !approvalFoundId ||
                !approvalFound.get(
                    approvalFoundId
                )
            ) {

                data.success =
                    false;

                data.message =
                    'The Found Item could not be found.';

                return;
            }


            /* ==================================================
               SECURITY DESK CUSTODY REQUIRED
            ================================================== */

            if (
                approvalFound.getValue(
                    'received_at_security_desk'
                ) != '1'
            ) {

                data.success =
                    false;

                data.message =
                    'Claim cannot be approved until the Found Item is received at the Security Desk.';

                return;
            }


            /* ==================================================
               APPROVE CLAIM
            ================================================== */

            approvalClaim.setValue(
                C_STATUS,
                CLAIM_APPROVED
            );


            if (
                approvalClaim.isValidField(
                    C_VERIFIED_BY
                )
            ) {

                approvalClaim.setValue(
                    C_VERIFIED_BY,
                    gs.getUserID()
                );
            }


            if (
                approvalClaim.isValidField(
                    C_VERIFIED_ON
                )
            ) {

                approvalClaim.setValue(
                    C_VERIFIED_ON,
                    new GlideDateTime()
                );
            }


            approvalClaim.update();


            /* ==================================================
               CONFIRM MATCH
            ================================================== */

            approvalMatch.setValue(
                M_STATUS,
                MATCH_CONFIRMED
            );


            approvalMatch.update();


            data.success =
                true;

            data.message =
                'Ownership verified. Claim approved and ready for collection.';

            return;
        }


        /* ==================================================
           REJECT CLAIM
        ================================================== */

        if (
            input.action ===
                'rejectClaim'
        ) {

            var rejectClaim =
                new GlideRecord(
                    CLAIM_TABLE
                );


            if (
                !claimId ||
                !rejectClaim.get(
                    claimId
                )
            ) {

                data.success =
                    false;

                data.message =
                    'Claim could not be found.';

                return;
            }


            var rejectClaimStatus =
                normalize(
                    rejectClaim.getValue(
                        C_STATUS
                    )
                );


            if (
                rejectClaimStatus ===
                    CLAIM_WITHDRAWN
            ) {

                data.success =
                    false;

                data.message =
                    'This Claim was withdrawn by the claimant and cannot be rejected again.';

                return;
            }


            if (
                rejectClaimStatus ===
                    'approved'
            ) {

                data.success =
                    false;

                data.message =
                    'An approved Claim cannot be rejected from this review page.';

                return;
            }


            if (
                rejectClaimStatus ===
                    'rejected'
            ) {

                data.success =
                    false;

                data.message =
                    'This Claim has already been rejected.';

                return;
            }


            rejectClaim.setValue(
                C_STATUS,
                CLAIM_REJECTED
            );


            if (
                rejectClaim.isValidField(
                    C_VERIFIED_BY
                )
            ) {

                rejectClaim.setValue(
                    C_VERIFIED_BY,
                    gs.getUserID()
                );
            }


            if (
                rejectClaim.isValidField(
                    C_VERIFIED_ON
                )
            ) {

                rejectClaim.setValue(
                    C_VERIFIED_ON,
                    new GlideDateTime()
                );
            }


            rejectClaim.update();


            data.success =
                true;

            data.message =
                'Claim rejected.';

            return;
        }
    }


    /* ======================================================
       PAGE MODE
    ====================================================== */

    if (claimId) {

        data.mode =
            'claim';

    }
    else if (matchId) {

        data.mode =
            'match';

    }
    else if (itemId) {

        data.mode =
            'item';

    }
    else {

        data.error =
            'No Item, Match or Claim was provided.';

        return;
    }


    /* ======================================================
       ITEM MODE
    ====================================================== */

    if (
        data.mode ===
            'item'
    ) {

        var item =
            loadItem(
                itemId
            );


        if (!item) {

            data.error =
                'Item record could not be found.';

            return;
        }


        data.item =
            itemObject(
                item
            );


        var related =
            new GlideRecord(
                MATCH_TABLE
            );


        var relatedQuery =
            related.addQuery(
                M_LOST,
                itemId
            );


        relatedQuery.addOrCondition(
            M_FOUND,
            itemId
        );


        related.orderByDesc(
            M_OVERALL
        );


        related.setLimit(
            20
        );


        related.query();


        while (
            related.next()
        ) {

            var lostId =
                related.getValue(
                    M_LOST
                );


            var foundId =
                related.getValue(
                    M_FOUND
                );


            var otherId =
                lostId === itemId
                    ?
                    foundId
                    :
                    lostId;


            var other =
                loadItem(
                    otherId
                );


            var relatedLevel =
                getMatchLevel(
                    related
                );


            var relatedStatus =
                normalize(
                    related.getValue(
                        M_STATUS
                    )
                );


            var relatedReviewed =
                isPotentialStaffVerified(
                    related
                );


            var reviewRequired =
                relatedLevel ===
                    'potential' &&
                !relatedReviewed &&
                relatedStatus !==
                    MATCH_REJECTED &&
                relatedStatus !==
                    'rejected' &&
                relatedStatus !==
                    MATCH_CONFIRMED &&
                relatedStatus !==
                    MATCH_WITHDRAWN &&
                relatedStatus !==
                    'resolved';


            data.relatedMatches.push({

                sys_id:
                    related.getUniqueValue(),

                otherItem:
                    other
                        ?
                        itemObject(
                            other
                        ).title
                        :
                        'CampusMatch Item',

                score:
                    numberValue(
                        related,
                        M_OVERALL
                    ),

                level:
                    display(
                        related,
                        M_LEVEL,
                        relatedLevel === 'potential'
                            ?
                            'Potential'
                            :
                            (
                                relatedLevel === 'strong'
                                    ?
                                    'Strong'
                                    :
                                    'Low'
                            )
                    ),

                levelValue:
                    relatedLevel,

                status:
                    display(
                        related,
                        M_STATUS,
                        '—'
                    ),

                statusValue:
                    relatedStatus,

                reviewRequired:
                    reviewRequired
            });
        }


        return;
    }


    /* ======================================================
       MATCH MODE
    ====================================================== */

    if (
        data.mode ===
            'match'
    ) {

        var match =
            new GlideRecord(
                MATCH_TABLE
            );


        if (
            !match.get(
                matchId
            )
        ) {

            data.error =
                'Match record could not be found.';

            return;
        }


        var lostItem =
            loadItem(
                match.getValue(
                    M_LOST
                )
            );


        var foundItem =
            loadItem(
                match.getValue(
                    M_FOUND
                )
            );


        if (
            !lostItem ||
            !foundItem
        ) {

            data.error =
                'One of the matched Item records could not be loaded.';

            return;
        }


        /* ==================================================
           MULTIPLE STRONG CANDIDATES

           IMPORTANT FIX:
           Count Strong matches for the SAME LOST ITEM.

           Example:

           Lost ITM001244
             ├── Found ITM001247 → 84.74 Strong
             └── Found ITM001248 → 83.60 Strong

           ambiguityCount = 2
        ================================================== */

        var candidateCount =
            0;


        var candidateQuery =
            new GlideRecord(
                MATCH_TABLE
            );


        candidateQuery.addQuery(
            M_LOST,
            match.getValue(
                M_LOST
            )
        );


        candidateQuery.addQuery(
            M_OVERALL,
            '>=',
            80
        );


        candidateQuery.query();


        while (
            candidateQuery.next()
        ) {

            var candidateStatus =
                normalize(
                    candidateQuery.getValue(
                        M_STATUS
                    )
                );


            /*
             * Closed candidates do not count.
             */

            if (
                candidateStatus ===
                    MATCH_REJECTED ||
                candidateStatus ===
                    'rejected' ||
                candidateStatus ===
                    MATCH_CONFIRMED ||
                candidateStatus ===
                    'resolved' ||
                candidateStatus ===
                    MATCH_WITHDRAWN
            ) {

                continue;
            }


            candidateCount++;
        }


        /* ==================================================
           CURRENT MATCH STATE
        ================================================== */

        var currentStatus =
            normalize(
                match.getValue(
                    M_STATUS
                )
            );


        var currentLevel =
            getMatchLevel(
                match
            );


        var currentOverall =
            numberValue(
                match,
                M_OVERALL
            );


        var staffVerifiedPotential =
            currentLevel ===
                'potential' &&
            isPotentialStaffVerified(
                match
            );


        var needsPotentialReview =
            currentLevel ===
                'potential' &&
            !staffVerifiedPotential &&
            currentStatus !==
                MATCH_REJECTED &&
            currentStatus !==
                'rejected' &&
            currentStatus !==
                MATCH_CONFIRMED &&
            currentStatus !==
                MATCH_WITHDRAWN &&
            currentStatus !==
                'resolved';


        /* ==================================================
           MATCH OBJECT
        ================================================== */

        data.match = {

            sys_id:
                match.getUniqueValue(),

            statusValue:
                currentStatus,

            withdrawn:
                currentStatus ===
                    MATCH_WITHDRAWN,

            actionsLocked:
                currentStatus ===
                    MATCH_WITHDRAWN ||
                currentStatus ===
                    MATCH_REJECTED ||
                currentStatus ===
                    'rejected' ||
                currentStatus ===
                    'resolved',

            levelValue:
                currentLevel,

            potentialStaffVerified:
                staffVerifiedPotential,

            needsPotentialReview:
                needsPotentialReview,

            ambiguityCount:
                candidateCount,

            overallScore:
                currentOverall,

            level:
                display(
                    match,
                    M_LEVEL,
                    currentLevel === 'strong'
                        ?
                        'Strong'
                        :
                        (
                            currentLevel === 'potential'
                                ?
                                'Potential'
                                :
                                'Low'
                        )
                ),

            status:
                display(
                    match,
                    M_STATUS,
                    '—'
                ),

            lost:
                itemObject(
                    lostItem
                ),

            found:
                itemObject(
                    foundItem
                ),

            factors:
                factorArray(
                    match
                )
        };


        data.matchReview =
            data.match;


        return;
    }


    /* ======================================================
       CLAIM MODE
    ====================================================== */

    if (
        data.mode ===
            'claim'
    ) {

        var claim =
            new GlideRecord(
                CLAIM_TABLE
            );


        if (
            !claim.get(
                claimId
            )
        ) {

            data.error =
                'Claim record could not be found.';

            return;
        }


        var relatedMatchId =
            claim.getValue(
                C_MATCH
            );


        var relatedMatch =
            null;


        if (relatedMatchId) {

            relatedMatch =
                new GlideRecord(
                    MATCH_TABLE
                );


            if (
                !relatedMatch.get(
                    relatedMatchId
                )
            ) {

                relatedMatch =
                    null;
            }
        }


        if (relatedMatch) {

            var relatedLost =
                loadItem(
                    relatedMatch.getValue(
                        M_LOST
                    )
                );


            var relatedFound =
                loadItem(
                    relatedMatch.getValue(
                        M_FOUND
                    )
                );


            var relatedMatchLevel =
                getMatchLevel(
                    relatedMatch
                );


            data.match = {

                sys_id:
                    relatedMatch.getUniqueValue(),

                overallScore:
                    numberValue(
                        relatedMatch,
                        M_OVERALL
                    ),

                level:
                    display(
                        relatedMatch,
                        M_LEVEL,
                        relatedMatchLevel === 'strong'
                            ?
                            'Strong'
                            :
                            (
                                relatedMatchLevel === 'potential'
                                    ?
                                    'Potential'
                                    :
                                    'Low'
                            )
                    ),

                status:
                    display(
                        relatedMatch,
                        M_STATUS,
                        '—'
                    ),

                statusValue:
                    normalize(
                        relatedMatch.getValue(
                            M_STATUS
                        )
                    ),

                withdrawn:
                    normalize(
                        relatedMatch.getValue(
                            M_STATUS
                        )
                    ) ===
                        MATCH_WITHDRAWN,

                explanation:
                    display(
                        relatedMatch,
                        M_EXPLANATION,
                        '—'
                    ),

                lost:
                    relatedLost
                        ?
                        itemObject(
                            relatedLost
                        )
                        :
                        null,

                found:
                    relatedFound
                        ?
                        itemObject(
                            relatedFound
                        )
                        :
                        null,

                factors:
                    factorArray(
                        relatedMatch
                    )
            };
        }


        var claimItem =
            loadItem(
                claim.getValue(
                    C_ITEM
                )
            );


        if (
            !claimItem &&
            relatedMatch
        ) {

            claimItem =
                loadItem(
                    relatedMatch.getValue(
                        M_FOUND
                    )
                );
        }


        var statusValue =
            normalize(
                claim.getValue(
                    C_STATUS
                )
            );


        var resultValue =
            normalize(
                claim.getValue(
                    C_RESULT
                )
            );


        data.claim = {

            sys_id:
                claim.getUniqueValue(),

            number:
                display(
                    claim,
                    C_NUMBER,
                    '—'
                ),

            claimant:
                display(
                    claim,
                    C_CLAIMANT,
                    '—'
                ),

            status:
                display(
                    claim,
                    C_STATUS,
                    '—'
                ),

            statusValue:
                statusValue,


            /* ==================================================
               WITHDRAWAL STATE
            ================================================== */

            withdrawn:
                statusValue ===
                    CLAIM_WITHDRAWN,


            /* ==================================================
               CLOSED CLAIM STATE
            ================================================== */

            actionsLocked:
                statusValue ===
                    CLAIM_WITHDRAWN ||
                statusValue ===
                    'rejected' ||
                statusValue ===
                    'cancelled' ||
                statusValue ===
                    'canceled' ||
                statusValue ===
                    'approved',


            /* ==================================================
               APPROVE BUTTON
            ================================================== */

            canApprove:
                statusValue !==
                    CLAIM_WITHDRAWN &&
                statusValue !==
                    'rejected' &&
                statusValue !==
                    'cancelled' &&
                statusValue !==
                    'canceled' &&
                statusValue !==
                    'approved',


            /* ==================================================
               REJECT BUTTON
            ================================================== */

            canReject:
                statusValue !==
                    CLAIM_WITHDRAWN &&
                statusValue !==
                    'rejected' &&
                statusValue !==
                    'cancelled' &&
                statusValue !==
                    'canceled' &&
                statusValue !==
                    'approved',


            claimDate:
                display(
                    claim,
                    C_DATE,
                    '—'
                ),


            verificationScore:
                numberValue(
                    claim,
                    C_SCORE
                ),


            verificationResult:
                resultValue,


            verificationDisplay:
                display(
                    claim,
                    C_RESULT,
                    '—'
                ),


            matchId:
                relatedMatchId,


            itemTitle:
                claimItem
                    ?
                    itemObject(
                        claimItem
                    ).title
                    :
                    'CampusMatch Item',


            found:
                claimItem
                    ?
                    {

                        receivedAtDesk:
                            claimItem.getValue(
                                'received_at_security_desk'
                            ) == '1',

                        receivedBy:
                            claimItem.getDisplayValue(
                                'received_by'
                            ) || '',

                        receivedOn:
                            claimItem.getDisplayValue(
                                'received_on'
                            ) || ''

                    }
                    :
                    {

                        receivedAtDesk:
                            false,

                        receivedBy:
                            '',

                        receivedOn:
                            ''

                    },


            expected1:
                claimItem
                    ?
                    display(
                        claimItem,
                        I_PRIVATE_1,
                        '—'
                    )
                    :
                    '—',


            expected2:
                claimItem
                    ?
                    display(
                        claimItem,
                        I_PRIVATE_2,
                        '—'
                    )
                    :
                    '—',


            expected3:
                claimItem
                    ?
                    display(
                        claimItem,
                        I_PRIVATE_3,
                        '—'
                    )
                    :
                    '—',


            answer1:
                display(
                    claim,
                    C_A1,
                    '—'
                ),


            answer2:
                display(
                    claim,
                    C_A2,
                    '—'
                ),


            answer3:
                display(
                    claim,
                    C_A3,
                    '—'
                )
        };


        return;
    }

})();
